                }
              }
            ],
            "deliverable": {
              "durationToleranceSeconds": 0.001
            }
          },
          "expect": "invalid",
          "fault": "INVALID_ARGUMENT",
          "schemaValid": false
        },
        {
          "id": "video-range",
          "reference": "examples/schemaxis/ffmpeg-video-range.json"
        },
