          "id": "audio-publish",
          "reference": "examples/schemaxis/ffmpeg-audio-publish.json"
        },
        {
          "id": "audio-publish-invalid",
          "reference": "examples/schemaxis/ffmpeg-audio-publish-invalid.json",
