                ]
              }
            ],
            "resources": {
              "/nodes/0/options/files/0": "examples/schemaxis/catalogue-texture.png"
            }
          },
          {
            "id": "deliverable-baseline",
            "example": "media-deliverable",
            "edits": [],
            "scope": "Known 2x2 RGBA PNG encoded as one FFV1 frame at 25 fps: declared dimensions/frame count, 0.04s native duration within 0.001s, file size below 100000 bytes, and exact decoded composited RGB. No perceptual or general encoding qualification.",
            "checks": [
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/deliverable/accepted",
                "expected": true
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/deliverable/observed/maximumMeanRGBError",
                "expected": 0.0
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/deliverable/observed/frames",
                "expected": 1
